using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
internal sealed partial class ModernWorkspace {
 string globalQuery="",globalKind="";
 void InstallSearchShortcut(){PreviewKeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.K&&(Keyboard.Modifiers&ModifierKeys.Control)!=0){e.Handled=true;Go("Recherche");}};}
 bool IsFavorite(string kind,string id){return store.Value.favorites.Any(f=>f.kind==kind&&f.id==id);}
 void ToggleFavorite(string kind,string id,string label){var existing=store.Value.favorites.FirstOrDefault(f=>f.kind==kind&&f.id==id);if(existing!=null)store.Value.favorites.Remove(existing);else{if(store.Value.favorites.Count>=200){MessageBox.Show("Vous pouvez conserver jusqu’à 200 favoris.");return;}store.Value.favorites.Add(new Favorite{kind=kind,id=id,label=label});}owner.Save();Refresh();}
 Button FavoriteButton(string kind,string id,string label){Button button=null;button=Btn(IsFavorite(kind,id)?"★  Épinglé":"☆  Épingler",delegate{ToggleFavorite(kind,id,label);button.Content=IsFavorite(kind,id)?"★  Épinglé":"☆  Épingler";},false,true);button.ToolTip="Ajouter ou retirer des favoris";return button;}
 void PinMenu(Control control,string kind,string id,string label){var menu=new ContextMenu{Background=SurfaceBrush,Foreground=Ink,BorderBrush=Line};var item=new MenuItem{Header=IsFavorite(kind,id)?"Retirer des favoris":"Épingler dans les favoris"};item.Click+=delegate{ToggleFavorite(kind,id,label);};menu.Items.Add(item);control.ContextMenu=menu;}
 void FavoriteSidebar(){var searchInfo=T("Ctrl + K · Rechercher",10,Muted,new Thickness(12,1,0,10));nav.Children.Add(searchInfo);var heading=new DockPanel{Margin=new Thickness(0,17,0,5)};var all=Btn("Gérer",delegate{Go("Favoris");},false,true);all.Padding=new Thickness(5);DockPanel.SetDock(all,Dock.Right);heading.Children.Add(all);heading.Children.Add(T("FAVORIS",9,Muted,new Thickness(10,5,0,0)));nav.Children.Add(heading);foreach(var favorite in store.Value.favorites.Take(6)){var f=favorite;var target=GlobalSearch.Resolve(store.Value,f);string title=target==null?(String.IsNullOrEmpty(f.label)?f.id:f.label):target.Title;var b=Btn("★  "+title,delegate{if(target!=null)OpenSearchItem(target);},false,true);b.HorizontalContentAlignment=HorizontalAlignment.Left;b.Padding=new Thickness(10,8,6,8);b.Margin=new Thickness(0,0,0,2);var text=T("★  "+title,11,target==null?Muted:Ink);text.TextTrimming=TextTrimming.CharacterEllipsis;b.Content=text;b.ToolTip=target==null?title+" · élément indisponible":GlobalSearch.KindName(target.Kind)+" · "+title;b.IsEnabled=target!=null;nav.Children.Add(b);}if(store.Value.favorites.Count==0)nav.Children.Add(T("Épinglez vos contenus\ndepuis la recherche.",10,Muted,new Thickness(10,4,0,10)));}
 void SearchPage(StackPanel root){var tools=new DockPanel{Margin=new Thickness(0,0,0,16)};var run=Btn("Rechercher",delegate{CommitSearch(tools);},true);DockPanel.SetDock(run,Dock.Right);tools.Children.Add(run);var types=new[]{"Tous les contenus","Tâches","Notes","Projets","Rendez-vous","Fichiers joints","Dossiers favoris","Modes","Google Drive","Idées à trier"};var filter=Combo(types,types[String.IsNullOrEmpty(globalKind)?0:Array.IndexOf(GlobalSearch.Kinds,globalKind)+1]);filter.Width=190;filter.Margin=new Thickness(10,0,10,0);filter.Tag="kind";DockPanel.SetDock(filter,Dock.Right);tools.Children.Add(filter);var search=new TextBox{Text=globalQuery,MaxLength=200,ToolTip="Chercher un titre, du texte, un projet ou un nom de fichier",Tag="query"};search.KeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Enter){globalQuery=search.Text;globalKind=filter.SelectedIndex==0?"":GlobalSearch.Kinds[filter.SelectedIndex-1];Refresh();e.Handled=true;}};tools.Children.Add(search);filter.SelectionChanged+=delegate{globalQuery=search.Text;globalKind=filter.SelectedIndex==0?"":GlobalSearch.Kinds[filter.SelectedIndex-1];Refresh();};root.Children.Add(tools);search.Loaded+=delegate{search.Focus();search.CaretIndex=search.Text.Length;};root.Children.Add(T("Recherche dans vos tâches, notes, projets et rendez-vous. Les fichiers joints sont recherchés par leur nom.",11,Muted,new Thickness(0,0,0,16)));var results=GlobalSearch.Find(store.Value,globalQuery,globalKind);root.Children.Add(T(results.Count+" résultat(s)"+(results.Count>60?" · 60 affichés, précisez votre recherche":""),12,Muted,new Thickness(0,0,0,15)));if(results.Count==0){root.Children.Add(Card("Aucun résultat",T("Essayez d’autres mots ou un autre type de contenu. Les notes à la corbeille sont exclues.",13,Muted)));return;}foreach(var result in results.Take(60)){var item=result;var body=new StackPanel();var top=new DockPanel();var star=FavoriteButton(item.Kind,item.Id,item.Title);star.Padding=new Thickness(10,6,10,6);DockPanel.SetDock(star,Dock.Right);top.Children.Add(star);var open=Btn(item.Title,delegate{OpenSearchItem(item);},false,true);open.HorizontalContentAlignment=HorizontalAlignment.Left;open.Padding=new Thickness(0,4,12,4);var title=T(item.Title,16);title.TextWrapping=TextWrapping.Wrap;open.Content=title;top.Children.Add(open);body.Children.Add(top);body.Children.Add(T(GlobalSearch.KindName(item.Kind)+" · "+item.Detail,11,Muted,new Thickness(0,6,0,0)));if(!String.IsNullOrWhiteSpace(item.Body)){string snippet=item.Body.Replace('\r',' ').Replace('\n',' ');body.Children.Add(T(snippet.Length>160?snippet.Substring(0,160)+"…":snippet,12,Muted,new Thickness(0,10,0,0)));}var card=Box(body,new Thickness(16));card.Margin=new Thickness(0,0,0,10);root.Children.Add(card);}}
 void CommitSearch(DockPanel tools){var queryInput=tools.Children.OfType<TextBox>().First();var kindInput=tools.Children.OfType<ComboBox>().First();globalQuery=queryInput.Text;globalKind=kindInput.SelectedIndex==0?"":GlobalSearch.Kinds[kindInput.SelectedIndex-1];Refresh();}
 void OpenSearchItem(SearchItem item){if(item.Kind=="inbox"){var idea=store.Value.inbox.FirstOrDefault(i=>i.id==item.Id);if(idea!=null)EditInbox(idea);return;}if(item.Kind=="google"){var pin=store.Value.googlePins.FirstOrDefault(p=>p.id==item.Id);if(pin!=null)OpenGoogleDocument(pin);}else if(item.Kind=="mode"){var mode=store.Value.modes.FirstOrDefault(m=>m.id==item.Id);if(mode!=null)RunMode(mode);}else if(item.Kind=="task"){var task=store.Value.tasks.FirstOrDefault(t=>t.id==item.Id);if(task!=null)owner.Edit(task);}else if(item.Kind=="note"){var note=store.Value.pages.FirstOrDefault(n=>n.id==item.Id&&!n.trashed);if(note!=null)ReadNote(note);}else if(item.Kind=="project")OpenProject(item.Id);else if(item.Kind=="event"){var appointment=store.Value.events.FirstOrDefault(e=>e.id==item.Id);if(appointment!=null)EditAppointment(appointment,Schedule.Day(appointment.date));}else if(item.Kind=="file"){var file=store.Value.projectData.SelectMany(p=>p.files).FirstOrDefault(f=>f.id==item.Id);if(file==null)return;string path=ProjectData.PathFor(store,file);if(!File.Exists(path)){MessageBox.Show("Cette pièce jointe est absente de ce PC. Transférez aussi le dossier Attachments pour la retrouver.");return;}OpenDocument(path);}else if(item.Kind=="folder"){if(!Directory.Exists(item.Id)){MessageBox.Show("Ce dossier est introuvable ou inaccessible sur ce PC.");return;}Open(item.Id);}}
 void FavoritesPage(StackPanel root){root.Children.Add(Btn("+  Ajouter un dossier du PC",delegate{using(var picker=new System.Windows.Forms.FolderBrowserDialog{Description="Choisissez un dossier à épingler",ShowNewFolderButton=false})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK){string path=picker.SelectedPath;if(IsFavorite("folder",path))return;string name=Path.GetFileName(path.TrimEnd(Path.DirectorySeparatorChar));ToggleFavorite("folder",path,String.IsNullOrEmpty(name)?path:name);}},true));root.Children.Add(T("Les six premiers favoris apparaissent dans la barre latérale. Retirer un favori conserve son contenu.",11,Muted,new Thickness(0,12,0,18)));if(store.Value.favorites.Count==0)root.Children.Add(T("Utilisez « Épingler » dans la recherche ou le clic droit sur une tâche.",13,Muted));for(int i=0;i<store.Value.favorites.Count;i++){int index=i;var favorite=store.Value.favorites[i];var target=GlobalSearch.Resolve(store.Value,favorite);string title=target==null?(String.IsNullOrEmpty(favorite.label)?favorite.id:favorite.label):target.Title;var body=new DockPanel();var controls=new StackPanel{Orientation=Orientation.Horizontal};controls.Children.Add(Btn("↑",delegate{MoveFavorite(index,-1);},false,true));controls.Children.Add(Btn("↓",delegate{MoveFavorite(index,1);},false,true));controls.Children.Add(Btn("Retirer",delegate{ToggleFavorite(favorite.kind,favorite.id,title);},false,true));DockPanel.SetDock(controls,Dock.Right);body.Children.Add(controls);var info=new StackPanel();var open=Btn(title,delegate{if(target!=null)OpenSearchItem(target);},false,true);open.HorizontalContentAlignment=HorizontalAlignment.Left;open.IsEnabled=target!=null;var text=T(title,14,target==null?Muted:Ink);text.TextWrapping=TextWrapping.Wrap;open.Content=text;info.Children.Add(open);info.Children.Add(T(GlobalSearch.KindName(favorite.kind)+(target==null?" · supprimé ou à la corbeille":" · "+target.Detail),11,Muted));body.Children.Add(info);var card=Box(body,new Thickness(12));card.Margin=new Thickness(0,0,0,10);root.Children.Add(card);}}
 void MoveFavorite(int index,int step){int destination=index+step;if(destination<0||destination>=store.Value.favorites.Count)return;var favorite=store.Value.favorites[index];store.Value.favorites.RemoveAt(index);store.Value.favorites.Insert(destination,favorite);owner.Save();Refresh();}
 internal void PreviewSearch(string path){var task=new WorkTask{id="preview-search-task",title="Préparer les plans du chantier",project="Travail",priority="Haute",status="doing",due=DateTime.Today.ToString("yyyy-MM-dd"),notes="Vérifier les surfaces et les quantitatifs avant envoi."};var note=new NotePage{id="preview-search-note",title="Notes de chantier",project="Travail",body="Points à vérifier sur les plans : cloisons, doublages et plafonds."};store.Value.tasks.Add(task);store.Value.pages.Add(note);var pin=new Favorite{kind="task",id=task.id,label=task.title};store.Value.favorites.Add(pin);selected="Recherche";globalQuery="chantier";Refresh();Preview(path+"-recherche.png");selected="Favoris";Refresh();Preview(path+"-favoris.png");store.Value.favorites.Remove(pin);store.Value.tasks.Remove(task);store.Value.pages.Remove(note);}
}
